"""Unit tests for lib/gcode_thumbnails.py: spec parsing, Moonraker-compatible block format,
insertion point, idempotence, mtime, G-code preview render."""
from __future__ import annotations

import base64
import os
import re
import struct
from pathlib import Path

import numpy as np
import pytest

import gcode_thumbnails as gt
from errors import InputNotFound

HEADER = (
    "; HEADER_BLOCK_START\n"
    "; generated by Snapmaker Orca 2.4.0 on 2026-10-13 at 13:19:55\n"
    "; total layer number: 2\n"
    "; HEADER_BLOCK_END\n"
    "\n"
    "; external perimeters extrusion width = 0.42mm\n"
)


def _box_moves() -> str:
    out = ["G90", "M83", "T1", ";TYPE:Outer wall"]
    for z in (0.2, 0.4, 0.6):
        out += [f"G1 Z{z}", "G1 X10 Y10", "G1 X30 Y10 E1", "G1 X30 Y30 E1", "G1 X10 Y30 E1", "G1 X10 Y10 E1"]
    out += [";TYPE:Prime tower", "G1 X100 Y100", "G1 X120 Y100 E1"]  # left out of the picture
    out += [";TYPE:Top surface", "G1 X10 Y10", "G2 X10 Y30 I0 J10 E0.5"]  # clockwise half circle through X0
    return "\n".join(out) + "\n"


def make_gcode(path: Path, spec: str | None = "48x48/PNG, 96x96/PNG", body: str | None = None) -> Path:
    tail = "; CONFIG_BLOCK_START\n; filament_colour = #FF0000;#00AA00\n"
    if spec is not None:
        tail += f"; thumbnails = {spec}\n"
    tail += "; CONFIG_BLOCK_END\n"
    path.write_text(HEADER + (body if body is not None else _box_moves()) + tail, encoding="ascii")
    return path


def _png_size(data: bytes) -> tuple[int, int]:
    assert data[:8] == b"\x89PNG\r\n\x1a\n"
    w, h = struct.unpack(">II", data[16:24])
    return w, h


def _moonraker_blocks(text: str) -> list[tuple[int, int, bytes]]:
    """Moonraker metadata.py BaseSlicer.parse_thumbnails, reduced to the parse."""
    out = []
    for m in re.finditer(r"(thumbnail(?:_[A-Za-z0-9]+)?) begin([;/\+=\w\s]+?); \1 end", text):
        lines = re.split(r"\r?\n", m.group(2).replace("; ", ""))
        info = [int(x) for x in re.findall(r"\d+", lines[0])]
        data = "".join(lines[1:-1])
        assert len(info) == 3 and len(data) == info[2]
        out.append((info[0], info[1], base64.b64decode(data)))
    return out


def test_parse_spec_orca_and_legacy_forms() -> None:
    assert gt.parse_spec("48x48/PNG, 300x300/PNG") == [gt.Thumb(48, 48, "PNG"), gt.Thumb(300, 300, "PNG")]
    assert gt.parse_spec("300x300, 96x96", "JPG") == [gt.Thumb(300, 300, "JPG"), gt.Thumb(96, 96, "JPG")]
    with pytest.raises(gt.ThumbnailError):
        gt.parse_spec("big")


def test_check_reports_missing_profile_sizes(tmp_path: Path) -> None:
    g = make_gcode(tmp_path / "a.gcode")
    c = gt.check(str(g))
    assert not c.ok
    assert c.required == [gt.Thumb(48, 48, "PNG"), gt.Thumb(96, 96, "PNG")]
    assert c.present == [] and c.missing == c.required
    assert "missing 48x48/PNG" in c.reason


def test_check_missing_file_raises_input_not_found(tmp_path: Path) -> None:
    with pytest.raises(InputNotFound):
        gt.check(str(tmp_path / "nope.gcode"))


def test_corrupt_payload_is_not_a_present_thumbnail() -> None:
    good = base64.b64encode(b"\x89PNG\r\n\x1a\n").decode()
    block = "; thumbnail begin 48x48 {n}\n; {d}\n; thumbnail end\n"
    assert gt._present(block.format(n=len(good), d=good)) == [gt.Thumb(48, 48, "PNG")]
    # Moonraker's length check alone accepts both: non-ASCII and non-base64 payloads of the declared length.
    assert gt._present(block.format(n=4, d="éééé")) == []
    assert gt._present(block.format(n=5, d="ab_cd")) == []


def test_ensure_writes_orca_blocks_after_header_that_moonraker_parses(tmp_path: Path) -> None:
    g = make_gcode(tmp_path / "a.gcode")
    c = gt.ensure(str(g))
    assert c.ok and c.added == [gt.Thumb(48, 48, "PNG"), gt.Thumb(96, 96, "PNG")]
    text = g.read_text(encoding="ascii")
    assert text.startswith(HEADER[: HEADER.index("; external")] + "; THUMBNAIL_BLOCK_START\n\n;\n; thumbnail begin 48x48 ")
    assert text.index("; THUMBNAIL_BLOCK_END") < text.index("\nG90")
    assert all(len(line) <= 2 + gt.ROW for line in text.splitlines() if line.startswith("; iVBOR") or
               (line.startswith("; ") and re.fullmatch(r"; [A-Za-z0-9+/=]+", line)))
    blocks = _moonraker_blocks(text)
    assert [(w, h) for w, h, _ in blocks] == [(48, 48), (96, 96)]
    assert [_png_size(d) for _, _, d in blocks] == [(48, 48), (96, 96)]
    assert text.endswith(_box_moves() + "; CONFIG_BLOCK_START\n; filament_colour = #FF0000;#00AA00\n"
                         "; thumbnails = 48x48/PNG, 96x96/PNG\n; CONFIG_BLOCK_END\n")


def test_ensure_is_idempotent_and_keeps_mtime(tmp_path: Path) -> None:
    g = make_gcode(tmp_path / "a.gcode")
    os.utime(g, (1_700_000_000, 1_700_000_000))
    gt.ensure(str(g))
    assert g.stat().st_mtime == 1_700_000_000
    once = g.read_bytes()
    again = gt.ensure(str(g))
    assert again.ok and again.added == []
    assert g.read_bytes() == once


def test_replace_redraws_every_size_without_duplicating_blocks(tmp_path: Path) -> None:
    g = make_gcode(tmp_path / "a.gcode")
    gt.ensure(str(g))
    first = g.read_text(encoding="ascii")
    c = gt.ensure(str(g), replace=True, source=lambda p: np.full((10, 10, 4), 255, np.uint8))
    text = g.read_text(encoding="ascii")
    assert c.added == [gt.Thumb(48, 48, "PNG"), gt.Thumb(96, 96, "PNG")]
    assert text.count("; THUMBNAIL_BLOCK_START") == 2 and text != first
    assert text.split("; THUMBNAIL_BLOCK_END\n\n")[-1] == first.split("; THUMBNAIL_BLOCK_END\n\n")[-1]
    assert text.startswith(HEADER[: HEADER.index("; external")] + "; THUMBNAIL_BLOCK_START")


def test_ensure_adds_only_the_missing_size_after_existing_blocks(tmp_path: Path) -> None:
    g = make_gcode(tmp_path / "a.gcode", spec="48x48/PNG")
    gt.ensure(str(g))
    text = g.read_text(encoding="ascii").replace("; thumbnails = 48x48/PNG", "; thumbnails = 48x48/PNG, 96x96/PNG")
    g.write_text(text, encoding="ascii")
    c = gt.ensure(str(g))
    assert c.added == [gt.Thumb(96, 96, "PNG")]
    assert [(w, h) for w, h, _ in _moonraker_blocks(g.read_text(encoding="ascii"))] == [(48, 48), (96, 96)]


def test_no_spec_needs_sizes_and_passes_with_any_thumbnail(tmp_path: Path) -> None:
    g = make_gcode(tmp_path / "a.gcode", spec=None)
    c = gt.check(str(g))
    assert not c.ok and c.required == []
    with pytest.raises(gt.ThumbnailError):
        gt.ensure(str(g))
    gt.ensure(str(g), sizes=[gt.Thumb(32, 32, "PNG")])
    assert gt.check(str(g)).ok


def test_unsupported_format_is_refused(tmp_path: Path) -> None:
    g = make_gcode(tmp_path / "a.gcode", spec="48x48/QOI")
    with pytest.raises(gt.ThumbnailError, match="QOI"):
        gt.ensure(str(g))
    assert "THUMBNAIL" not in g.read_text(encoding="ascii")


def test_out_leaves_source_untouched(tmp_path: Path) -> None:
    g = make_gcode(tmp_path / "a.gcode")
    before = g.read_bytes()
    gt.ensure(str(g), out=str(tmp_path / "b.gcode"))
    assert g.read_bytes() == before
    assert gt.check(str(tmp_path / "b.gcode")).ok


def test_out_of_an_already_complete_file_keeps_its_mtime(tmp_path: Path) -> None:
    # A copy stamped "now" would look newer than its project and pass a staleness check.
    g = make_gcode(tmp_path / "a.gcode")
    gt.ensure(str(g))
    os.utime(g, (1_700_000_000, 1_700_000_000))
    out = tmp_path / "b.gcode"
    gt.ensure(str(g), out=str(out))
    assert out.read_bytes() == g.read_bytes()
    assert out.stat().st_mtime == 1_700_000_000


def test_add_always_provisions_pillow_for_jpg_profiles(monkeypatch: pytest.MonkeyPatch, tmp_path: Path) -> None:
    # A `; thumbnails = 300x300/JPG` profile is encoded through Pillow even without --image.
    from commands import gcode_thumbnails as cmd

    seen: list[str] = []

    def fake_exec_tool(deps: str, script: str, args: list[str]) -> int:
        seen.append(deps)
        return 0

    monkeypatch.setattr(cmd, "exec_tool", fake_exec_tool)
    g = make_gcode(tmp_path / "a.gcode", spec="300x300/JPG")
    assert cmd.run(["add", str(g)]) == 0
    assert seen == ["numpy,pillow"]


def test_ensure_refuses_when_the_file_is_replaced_while_rendering(tmp_path: Path) -> None:
    g = make_gcode(tmp_path / "a.gcode")
    fresh = make_gcode(tmp_path / "fresh.gcode", body="G90\nG1 X1 Y1 E1\n").read_bytes()

    def reslice_lands(path: str) -> np.ndarray:
        pic = gt.render_gcode(path, size=96)
        tmp = tmp_path / "landing"
        tmp.write_bytes(fresh)
        os.replace(tmp, path)  # e.g. deliver.sh copying a new slice over it
        return pic

    with pytest.raises(gt.ThumbnailError, match="changed"):
        gt.ensure(str(g), source=reslice_lands)
    assert g.read_bytes() == fresh


def test_toolpaths_skip_hidden_features_and_follow_tools_and_arcs() -> None:
    import io

    seg = gt.toolpaths(io.BytesIO(_box_moves().encode()))
    s = np.frombuffer(seg, np.float64).reshape(-1, 6)
    assert s[:, 0].max() <= 30.0  # prime tower at X100-120 left out
    assert s[:, 0].min() < 0.5  # the G2 half circle bulges to X0
    assert set(s[:, 5].tolist()) == {1.0}
    assert len(s) > 12  # 12 wall segments + the arc split into pieces
    assert sorted(set(s[:, 4].round(3).tolist())) == [0.2, 0.4, 0.6]


def test_render_is_coloured_by_tool_on_transparent_background(tmp_path: Path) -> None:
    g = make_gcode(tmp_path / "a.gcode")
    img = gt.render_gcode(str(g), size=120)
    assert img.dtype == np.uint8 and img.shape[2] == 4
    alpha = img[..., 3]
    assert alpha[0, 0] == 0 and (alpha == 255).any()
    lit = img[alpha == 255][:, :3].astype(int)
    assert (lit[:, 1] > lit[:, 0]).all()  # T1 = #00AA00: green dominates every drawn pixel


def test_fit_keeps_aspect_with_transparent_margins() -> None:
    src = np.zeros((10, 40, 4), np.uint8)
    src[...] = (255, 0, 0, 255)
    out = gt.fit(src, 20, 20)
    assert out.shape == (20, 20, 4)
    assert out[0, 10, 3] == 0 and out[10, 10, 3] == 255 and out[10, 10, 0] == 255


def test_encode_png_round_trips_size() -> None:
    img = np.zeros((7, 5, 4), np.uint8)
    assert _png_size(gt.encode_png(img)) == (5, 7)
